import{t as e}from"./utils-COoNfFoj.js";var t={slug:`alec-steele-2`,influencerName:`Alec Steele`,influencerHandle:`@alecsteele`,influencerAvatarUrl:`${e}/alec-steele-2-avatar.png`,multiAsset:!0,heroTitle:`Alec's Computer Builds`,assets:[{title:`Conversational Plasma DXF Generator`,imageUrl:`${e}/alec-steele-2-conversational-plasma-dxf-generator.png`,quote:`I wanted a tool to generate simple plasma-cutting DXF files quickly from my phone, using speech-to-text or a short text input. This will be a real time saver compared to opening CAD every time I need a gusset, disc or flange.`,promptText:`Create a mobile-friendly web app that turns typed or dictated plain-English part descriptions into simple plasma-cutting DXF files, with live geometry preview, editable extracted parameters, metric/inch support, and share/save export options. Keep it lightweight, supporting common shop shapes like flanges, plates, rectangles, squares, holes, slots, triangles, and rounded external corner radii.`,remixUrl:`https://www.perplexity.ai/computer/a/295047f9-5948-48ea-9f75-dc3e2019f215`},{title:`Hole and Shaft Fits Calculator`,imageUrl:`${e}/alec-steele-2-hole-and-shaft-fits-calculator.png`,quote:`Making parts fit exactly how you want is hard, even at the design stage. Whether a part should run freely, press together firmly, or require serious force to assemble and disassemble is far more complex than it may seem. I wanted a user-friendly app to demystify these calculations and reference tables. Perplexity Computer pulled it off in one prompt.`,promptText:`Create a clean, mobile-responsive engineering fits calculator that can be embedded into a website. Let users choose hole-basis or shaft-basis, enter metric or imperial nominal diameter, select common clearance, transition, and interference fits, and output drawing-ready callouts, tolerance limits, and clearance/interference ranges. Base the calculations on reliable engineering standards and cross-checked reference tables, include concise explanations, and unit toggles.`,remixUrl:`https://www.perplexity.ai/computer/a/fad630e7-9005-4fe9-b4a5-c52e79617ede`},{title:`Single-Point Threading Calculator`,imageUrl:`${e}/alec-steele-2-single-point-threading-calculator.png`,quote:`Single-point threading is a daunting task at the lathe and is only pulled off with the correct numbers. I saw this as the perfect place to use Perplexity to make the app I wish had existed since I first started using a metal lathe.`,promptText:`Build a mobile-friendly web calculator for single-point lathe threading. Cover metric, UNC/UNF, Whitworth, BSP/BSPT, NPT and NPSM threads with editable dimensions, metric/imperial toggles, and outputs for thread depth, pitch diameter, crossfeed, compound infeed and pass progression. Include clear 60°/55° compound-angle conventions and practical machining cautions.`,remixUrl:`https://www.perplexity.ai/computer/a/5f6be548-c5e6-40b5-9704-2bcd5ba02865`}]};export{t as default};
